import type { Metadata, Viewport } from 'next';
import { copy, languageAlternates, LOCALE_META, LOCALES, localePath, splitLocale, type Locale, type Translated, type TranslatedPath } from '@/content/i18n';
import { site } from '@/content/site';
import { SITE_URL } from '@/lib/site-url';

/** Default social preview (1200×630) in each language, generated by scripts/og-image.mjs. */
const OG_IMAGES: Record<Locale, { url: string; width: number; height: number; alt: string }> = {
  en: { url: '/images/og/parsa-alizadeh.png', width: 1200, height: 630, alt: `${site.name}, software developer` },
  fa: { url: '/images/og/parsa-alizadeh-fa.png', width: 1200, height: 630, alt: `${copy.fa.name} (${site.name})، توسعه‌دهنده‌ی نرم‌افزار` },
  tr: { url: '/images/og/parsa-alizadeh-tr.png', width: 1200, height: 630, alt: `${site.name}, yazılım geliştirici` }
};
export const DEFAULT_OG_IMAGE = OG_IMAGES.en;

export const siteViewport: Viewport = {
  viewportFit: 'cover',
  themeColor: [
    { media: '(prefers-color-scheme: light)', color: '#F1F2EE' },
    { media: '(prefers-color-scheme: dark)', color: '#0F1112' }
  ]
};

/** Site-wide defaults for a language's root layout. */
export function baseMetadata(locale: Locale, defaultTitle: string, description: string): Metadata {
  return {
    metadataBase: new URL(SITE_URL),
    title: { default: defaultTitle, template: `%s – ${site.name}` },
    description,
    applicationName: site.name,
    authors: [{ name: site.name, url: SITE_URL }],
    creator: site.name,
    publisher: site.name,
    // Canonical URLs are set per page (pageMetadata below), so error pages never inherit one.
    alternates: {
      types: { 'application/rss+xml': [{ url: '/blog/rss.xml', title: `Blog – ${site.name}` }] }
    },
    openGraph: { type: 'website', siteName: site.name, locale: LOCALE_META[locale].og, url: '/', images: [OG_IMAGES[locale]] },
    twitter: { card: 'summary_large_image', images: [OG_IMAGES[locale].url] },
    robots: {
      index: true,
      follow: true,
      googleBot: { index: true, follow: true, 'max-image-preview': 'large', 'max-snippet': -1, 'max-video-preview': -1 }
    },
    formatDetection: { telephone: false, email: false, address: false },
    // Google Search Console HTML-tag verification: set GOOGLE_SITE_VERIFICATION to the code only.
    ...(process.env.GOOGLE_SITE_VERIFICATION ? { verification: { google: process.env.GOOGLE_SITE_VERIFICATION } } : {})
  };
}

interface PageMeta {
  /** Full <title>; not passed through the layout's template. */
  title: string;
  description: string;
  /** Path of the canonical URL, e.g. "/blog/offline-sync" or "/fa/about". */
  path: string;
  type?: 'website' | 'profile' | 'article';
  image?: { url: string; width?: number; height?: number; alt: string };
  article?: { publishedTime: string; modifiedTime: string; tags: string[]; section: string };
  /** Languages this page exists in, for hreflang. Default: all; articles pass the ones translated. */
  locales?: readonly Locale[];
}

/**
 * Complete per-page metadata. Next.js replaces (not merges) the parent's openGraph object,
 * so every page gets the full set: canonical, Open Graph and Twitter card, and hreflang links
 * to the same page in its other languages.
 */
export function pageMetadata({ title, description, path, type = 'website', image: given, article, locales = LOCALES }: PageMeta): Metadata {
  const { locale, path: base } = splitLocale(path);
  const image = given ?? OG_IMAGES[locale];
  const translated = locales.length > 1;
  return {
    title: { absolute: title },
    description,
    alternates: { canonical: path, ...(translated ? { languages: languageAlternates(base, locales) } : {}) },
    openGraph: {
      type,
      url: path,
      siteName: site.name,
      locale: LOCALE_META[locale].og,
      ...(translated ? { alternateLocale: locales.filter(l => l !== locale).map(l => LOCALE_META[l].og) } : {}),
      title,
      description,
      images: [image],
      ...(type === 'profile' ? { firstName: site.firstName, lastName: site.lastName } : {}),
      ...(type === 'article' && article
        ? { publishedTime: article.publishedTime, modifiedTime: article.modifiedTime, authors: [site.name], tags: article.tags, section: article.section }
        : {})
    },
    twitter: { card: 'summary_large_image', title, description, images: [image.url] }
  };
}

/** Metadata for a page of the Persian or Turkish site, from its copy in content/i18n.ts. */
export const translatedMetadata = (locale: Translated, path: TranslatedPath, type?: PageMeta['type']): Metadata =>
  pageMetadata({ ...copy[locale].meta[path], path: localePath(locale, path), type });
